import{_ as t,o as a,c as s,ag as r}from"./chunks/framework.2cFhd8Ux.js";const g=JSON.parse('{"title":"Week 4 — Securing Agents","description":"","frontmatter":{"source":"weeks/04-securing-agents/README.md"},"headers":[],"relativePath":"weeks/04-securing-agents/index.md","filePath":"weeks/04-securing-agents/index.md"}'),o={name:"weeks/04-securing-agents/index.md"};function n(i,e,l,d,h,c){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="week-4--securing-agents" tabindex="-1">Week 4 — Securing Agents <a class="header-anchor" href="#week-4--securing-agents" aria-label="Permalink to &quot;Week 4 — Securing Agents&quot;">​</a></h1><blockquote><p>An agent that reads untrusted text and holds a tool that reaches the network can be made to leak your secrets. The defenses that hold are architectural, not instructions.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before the Seminar</strong></td><td>Read the reading, post your reading response, submit the week 3 A/B test (the Seminar opens with its quiz); if a graduate paper is presented, post one question (<a href="./../../graduate/paper-presentations.html#questions-from-the-class">how</a>)</td></tr><tr><td><strong>Seminar</strong></td><td>Due-date quiz (7 min, 🔴 AI off) · talk: injection, the lethal trifecta, tool poisoning, permissions, sandboxes, secrets, defense patterns (<a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-04.html" target="_blank" rel="noreferrer">slides</a>) · case jigsaw (A1, A2, A4, A5) or a graduate paper · demo · Lab preview</td></tr><tr><td><strong>Lab</strong></td><td><a href="./lab.html#lab--the-injection-lab-75-min">Injection lab</a>: attack on localhost, read the trace, enable each defense. <strong>Checkoff:</strong> attack succeeds, then fails under two defenses, one bypass named</td></tr><tr><td><strong>Due before next week&#39;s Seminar</strong></td><td>Default 11:59 pm the night before: the <a href="./lab.html#assignment--a-defense-and-a-threat-model">assignment</a> — extend one defense (<code>EXTEND:</code> marker) with tests, plus a <code>THREAT_MODEL.md</code> of your team&#39;s setup</td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: defense code and tests · 🟡 AI limited: the threat model (AI may brainstorm attacks, logged; analysis is yours) · 🔴 AI off: quiz, reading response, naming bypasses</td></tr><tr><td><strong>Reading</strong></td><td>Simon Willison, <a href="https://simonwillison.net/2025/Jul/6/supabase-mcp-lethal-trifecta/" target="_blank" rel="noreferrer">&quot;Supabase MCP can leak your entire SQL database&quot;</a> (Jul 2025)</td></tr><tr><td><strong>Reading response</strong></td><td>150–250 words on Canvas, 🔴 AI off, before the Seminar (prompt <a href="#reading">below</a>)</td></tr><tr><td><strong>Team project</strong></td><td>Your team writes <code>course/THREAT_MODEL.md</code> for its agent setup <strong>before</strong> giving an agent broad access to the fork (<a href="./../../project/milestones.html">milestones</a>); revised at M2 and before the final presentation</td></tr><tr><td><strong>Graduate track</strong></td><td>A paper presentation if scheduled (Liu et al., CaMeL, or the design-patterns paper) (<a href="./../../graduate/paper-presentations.html">paper presentations</a>)</td></tr><tr><td><strong>Time</strong></td><td>Meetings 2.5 h · outside about 6 h (CS [5xxx]: about 7.5 h)</td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>The injection lab is an attack, harmless on purpose: it targets <strong>only 127.0.0.1 (your own machine)</strong> and a <strong>fake canary</strong> (<code>CANARY-…</code>) worth nothing. <strong>Never</strong> point it at a real host, a real secret, or anyone else&#39;s machine, and never move the attacker URL off loopback. Prefer a <strong>local model</strong> so nothing leaves your computer, and run it in a sandbox (<a href="./../../setup/safety-contract.html#3-untrusted-code-runs-in-a-sandbox">rule 3</a>).</p></div><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Define <a href="./../../resources/glossary.html#prompt-injection">prompt injection</a>, <a href="./../../resources/glossary.html#prompt-injection">direct</a> and <a href="./../../resources/glossary.html#indirect-prompt-injection">indirect</a>, and explain the <a href="./../../resources/glossary.html#lethal-trifecta">lethal trifecta</a> — private data, untrusted content, a way out, in one session.</li><li>Explain <a href="./../../resources/glossary.html#tool-poisoning">MCP tool poisoning</a> and <a href="./../../resources/glossary.html#excessive-agency">over-broad tools</a>, and why the trifecta&#39;s legs are counted <em>per session</em>, not <em>per tool</em>.</li><li>Run an indirect-injection attack and read the trace to see how the injected text steered the agent.</li><li>Enable four defenses, say which leg each removes, and name a bypass for each — especially the egress filter.</li><li>Write a threat model of your team&#39;s agent setup: assets, trust boundaries, the per-session trifecta check, controls, residual risk.</li></ol><h2 id="seminar" tabindex="-1">Seminar <a class="header-anchor" href="#seminar" aria-label="Permalink to &quot;Seminar&quot;">​</a></h2><p>Due-date quiz on the week 3 A/B test (7 min, 🔴 AI off, <a href="./../../assessment/quizzes.html">quizzes</a>) · concept talk (25 min, <a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-04.html" target="_blank" rel="noreferrer">slides</a>) · case jigsaw (A1, A2, A4, A5, <a href="./../../resources/case-studies.html#using-these-in-class">case studies</a>) or a graduate presentation (20 min) · live demo (10 min) · Lab preview (5 min).</p><h2 id="lab" tabindex="-1">Lab <a class="header-anchor" href="#lab" aria-label="Permalink to &quot;Lab&quot;">​</a></h2><p>The <a href="./lab.html#lab--the-injection-lab-75-min">lab</a> uses the <a href="https://github.com/Boyu-Zhang-UOI/eswa-injection-lab" target="_blank" rel="noreferrer"><code>injection-lab</code> kit</a>: a poisoned <code>README.md</code> and issue try to make your <code>mini-agent</code> read a fake canary from <code>.env</code> and send it to an &quot;attacker&quot; on localhost. You attack, read the <a href="./../../resources/glossary.html#trace">trace</a>, then turn on each defense and explain how it&#39;s bypassed. The <a href="./lab.html#assignment--a-defense-and-a-threat-model">assignment</a> extends one defense with tests and threat-models your team&#39;s setup — before teams give agents broad access to the fork.</p><h2 id="reading" tabindex="-1">Reading <a class="header-anchor" href="#reading" aria-label="Permalink to &quot;Reading&quot;">​</a></h2><p><strong>Simon Willison, <a href="https://simonwillison.net/2025/Jul/6/supabase-mcp-lethal-trifecta/" target="_blank" rel="noreferrer">&quot;Supabase MCP can leak your entire SQL database&quot;</a></strong> (Jul 2025). An agent holding a database key that bypasses row-level security handles support tickets; a ticket carries instructions, and the agent copies secrets into a reply the attacker can read. One server supplied all three legs of the lethal trifecta; making it read-only removes the way out (<a href="./../../resources/case-studies.html#a1-supabase-mcp-the-lethal-trifecta-in-one-server">case A1</a>).</p><p><strong>Reading response prompt</strong> (150–250 words, 🔴 AI off, on Canvas): Name the three legs of the trifecta in this incident. Argue for the <em>single</em> change that removes the most risk (a read-only key, a separate tool-less reading session, or an approval on every write) and say what it gives up. End with how your <code>mini-agent</code> lab sessions map onto the three legs, and one question for the Seminar. More readings: <a href="./../../resources/reading-list.html#week-4--securing-agents">reading list, week 4</a>.</p><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><ul><li><strong>Prompt injection.</strong> Text that makes a model follow instructions its user didn&#39;t give. <em>Direct</em> comes from the user&#39;s input; <em>indirect</em> arrives in content the agent reads — an issue, a README, a web page, a tool result (<a href="./../../resources/glossary.html#indirect-prompt-injection">glossary</a>). The lab&#39;s attack is indirect. &quot;The model will notice&quot; is no defense: planted payloads made production editors run malicious commands up to 84% of the time (<a href="https://arxiv.org/abs/2509.22040" target="_blank" rel="noreferrer">Liu et al.</a>); defenses must be structural.</li><li><strong>The lethal trifecta.</strong> An agent is dangerous to its user with <strong>private data</strong>, exposure to <strong>untrusted content</strong>, and a <strong>way to send data out</strong>, all in one session. Remove any one leg and the attack can&#39;t complete. Count legs per <em>session</em>, not per tool (<a href="./../../resources/case-studies.html#a1-supabase-mcp-the-lethal-trifecta-in-one-server">case A1</a>).</li><li><strong>Tool poisoning and over-broad tools.</strong> A tool&#39;s description is a prompt the model reads; a malicious server can hide instructions there and change them after approval (<a href="./../../resources/case-studies.html#a3-mcp-tool-poisoning-instructions-the-user-never-sees">case A3</a>). <code>run_command</code> hands the agent far more than triage needs; least privilege applies to tools (<a href="./../../resources/glossary.html#excessive-agency">excessive agency</a>).</li><li><strong>Four defenses, one per leg.</strong> A <strong>tool allowlist</strong> removes the way out; <strong>approvals</strong> keep a human on every command; an <strong>egress block</strong> tries to stop network calls; <strong>quarantined reading</strong> removes exposure — a tool-less model summarizes untrusted text first (the dual-LLM pattern).</li><li><strong>String filters are guard rails, not sandboxes.</strong> The egress block inspects a <em>string</em>, which hides a host many ways (an IP in decimal or hex, a variable, a file, another tool); <code>mini-agent</code> won&#39;t allowlist a command with shell control characters, but an allowlisted command still runs with your full permissions. Containment and real egress control live in the network/sandbox layer (<a href="./../../setup/sandboxes.html#what-a-sandbox-does-and-doesnt-protect">sandboxes</a>).</li><li><strong>Rules are advice; setup is enforcement.</strong> &quot;The agent won&#39;t read <code>.env</code>&quot; is not a control; the control is no <code>.env</code> in reach, a read-only token, an egress allowlist, approvals on.</li></ul><h2 id="check-your-understanding" tabindex="-1">Check your understanding <a class="header-anchor" href="#check-your-understanding" aria-label="Permalink to &quot;Check your understanding&quot;">​</a></h2><ol><li>The attack works against a model told in its system prompt to ignore instructions in files. Why design defenses as if the model always obeys?</li><li>Which leg of the trifecta does each defense remove: tool allowlist, approvals, egress block, quarantined reading?</li><li>Write one command that sends the canary to <code>127.0.0.1</code> and defeats the egress filter&#39;s string check. Why does it get through?</li><li>Quarantine still passes untrusted text to a model (the summarizer). Why is that model much less dangerous than the main agent, and what can it still do wrong?</li></ol><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><ul><li><strong>No free-tier model for the live agent:</strong> use the lab machine&#39;s Ollama or a laptop model (<a href="./../../setup/local-models.html">local models</a>) — safest anyway. If yours refuses the injection, use the kit&#39;s <strong>stubbed obedient model</strong> (how the tests run) to show the mechanism, and say so.</li><li><strong>The attacker port is busy:</strong> <code>PORT=9000 node attacker-server.mjs</code>; <code>lab.mjs</code> fills the placeholder.</li><li><strong>Everything is down:</strong> <code>npm test</code> runs the whole attack-and-defense cycle offline with a stub model and no key. MCP issues: <a href="./../../resources/troubleshooting.html#mcp-the-server-wont-connect">troubleshooting</a>.</li></ul><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>Debenedetti et al., <a href="https://arxiv.org/abs/2503.18813" target="_blank" rel="noreferrer">&quot;CaMeL&quot;</a> and Beurer-Kellner et al., <a href="https://arxiv.org/abs/2506.08837" target="_blank" rel="noreferrer">&quot;Design Patterns for Securing LLM Agents&quot;</a>: the patterns behind quarantine (both <a href="./../../graduate/paper-presentations.html">graduate seminar</a> papers). The <a href="https://modelcontextprotocol.io/specification/2026-07-28/basic/security_best_practices" target="_blank" rel="noreferrer">MCP Security Best Practices</a> catalogue and the <a href="https://genai.owasp.org/resource/owasp-genai-llm-top-10-2026/" target="_blank" rel="noreferrer">OWASP GenAI LLM Top 10 2026</a> are checklists for the threat model; Anthropic&#39;s <a href="https://www.anthropic.com/engineering/claude-code-sandboxing" target="_blank" rel="noreferrer">&quot;Beyond permission prompts&quot;</a> explains why filesystem <em>and</em> network isolation are both needed.</li><li>Previous week: <a href="./../03-context-engineering/">Context Engineering</a>. Next week: <a href="./../05-spec-driven-development/">Spec-Driven Development</a>, where teams build in the class fork — threat model done.</li></ul>',23)])])}const m=t(o,[["render",n]]);export{g as __pageData,m as default};
